<PageTitle>Job Application</PageTitle>

<h2 class="mb-4">Job Application</h2>

@if (Submitted)
{
    <div class="card border-success">
        <div class="card-body text-center py-5">
            <div class="text-success mb-3" style="font-size: 3rem;">✔</div>
            <h3 class="card-title text-success">Application Submitted!</h3>
            <p class="card-text mt-3">Your application has been received. Your confirmation number is:</p>
            <h4 class="fw-bold">@SubmittedApplicationId</h4>
        </div>
    </div>
}
else
{
    <StepIndicator CurrentStep="CurrentStep"
                   CompletedSteps="CompletedSteps"
                   OnStepClicked="GoToStep" />

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger mt-3" role="alert">@ErrorMessage</div>
    }

    <div class="mt-4">
        @switch (CurrentStep)
        {
            case 1:
                <StepPersonalInfo FullName="@FullName" Email="@Email" Phone="@Phone" Address="@Address"
                                  FullNameChanged="v => FullName = v"
                                  EmailChanged="v => Email = v"
                                  PhoneChanged="v => Phone = v"
                                  AddressChanged="v => Address = v" />
                <StepNavigation CurrentStep="1" OnNext="NextStep" IsProcessing="IsProcessing" />
                break;

            case 2:
                <StepWorkHistory Entries="WorkEntries" />
                <StepNavigation CurrentStep="2" OnBack="PreviousStep" OnNext="NextStep" />
                break;

            case 3:
                <StepReferences References="References" />
                <StepNavigation CurrentStep="3" OnBack="PreviousStep" OnNext="NextStep" />
                break;

            case 4:
                <StepCoverLetter CoverLetter="@CoverLetter"
                                 CoverLetterChanged="v => CoverLetter = v" />
                <StepNavigation CurrentStep="4" OnBack="PreviousStep" OnNext="NextStep" />
                break;

            case 5:
                <StepReview FullName="@FullName" Email="@Email" Phone="@Phone" Address="@Address"
                            WorkEntries="WorkEntries" References="References" CoverLetter="@CoverLetter"
                            OnEditSection="GoToStep" />
                <div class="d-flex justify-content-between mt-4">
                    <button class="btn btn-outline-secondary" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@IsProcessing">
                        @if (IsProcessing)
                        {
                            <span class="spinner-border spinner-border-sm me-2" role="status"></span>
                        }
                        Submit Application
                    </button>
                </div>
                break;
        }
    </div>
}

@code {
    private int CurrentStep { get; set; } = 1;
    private HashSet<int> CompletedSteps { get; set; } = new();
    private bool IsProcessing { get; set; }
    private string? ErrorMessage { get; set; }
    private bool Submitted { get; set; }
    private int SubmittedApplicationId { get; set; }

    // Step 1
    private string FullName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Phone { get; set; } = "";
    private string Address { get; set; } = "";

    // Step 2
    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };

    // Step 3
    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4
    private string CoverLetter { get; set; } = "";

    private async Task NextStep()
    {
        ErrorMessage = null;

        if (!await ValidateCurrentStep())
            return;

        CompletedSteps.Add(CurrentStep);
        CurrentStep++;
    }

    private void PreviousStep()
    {
        ErrorMessage = null;
        if (CurrentStep > 1)
            CurrentStep--;
    }

    private void GoToStep(int step)
    {
        ErrorMessage = null;
        if (step < CurrentStep || CompletedSteps.Contains(step))
            CurrentStep = step;
    }

    private async Task<bool> ValidateCurrentStep()
    {
        switch (CurrentStep)
        {
            case 1:
                if (string.IsNullOrWhiteSpace(FullName))
                { ErrorMessage = "Full name is required."; return false; }
                if (string.IsNullOrWhiteSpace(Email))
                { ErrorMessage = "Email is required."; return false; }
                if (string.IsNullOrWhiteSpace(Phone))
                { ErrorMessage = "Phone number is required."; return false; }
                if (string.IsNullOrWhiteSpace(Address))
                { ErrorMessage = "Address is required."; return false; }

                IsProcessing = true;
                StateHasChanged();
                var emailValid = await ApplicationService.ValidateEmailAsync(Email);
                IsProcessing = false;
                if (!emailValid)
                { ErrorMessage = "Please enter a valid email address."; return false; }
                break;

            case 2:
                foreach (var entry in WorkEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
                    { ErrorMessage = "Company name and job title are required for all work entries."; return false; }
                    if (entry.StartDate == default)
                    { ErrorMessage = "Start date is required for all work entries."; return false; }
                }
                break;

            case 3:
                foreach (var r in References)
                {
                    if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Email))
                    { ErrorMessage = "Name and email are required for all references."; return false; }
                }
                break;

            case 4:
                if (string.IsNullOrWhiteSpace(CoverLetter))
                { ErrorMessage = "Cover letter is required."; return false; }
                break;
        }
        return true;
    }

    private async Task SubmitApplication()
    {
        IsProcessing = true;
        ErrorMessage = null;
        StateHasChanged();

        try
        {
            var personal = new PersonalInfo(FullName, Email, Phone, Address);
            var workHistory = new WorkHistory(WorkEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
            var refs = References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, workHistory, refs, CoverLetter);

            SubmittedApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            Submitted = true;
        }
        catch
        {
            ErrorMessage = "An error occurred while submitting your application. Please try again.";
        }
        finally
        {
            IsProcessing = false;
        }
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    public class ReferenceModel
    {
