toolArgs.file_text:
.step-indicator {
    display: flex;
    justify-content: space-between;
    position: relative;
    padding: 0;
    list-style: none;
    counter-reset: step;
}

.step-indicator::before {
    content: '';
    position: absolute;
    top: 20px;
    left: 10%;
    right: 10%;
    height: 3px;
    background: #dee2e6;
    z-index: 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    position: relative;
    z-index: 1;
    flex: 1;
    cursor: default;
}

.step-item.clickable {
    cursor: pointer;
}

.step-circle {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: #dee2e6;
    color: #6c757d;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
    transition: all 0.2s;
}

.step-item.active .step-circle {
    background: #0d6efd;
    color: white;
}

.step-item.completed .step-circle {
    background: #198754;
    color: white;
}

.step-label {
    font-size: 0.8rem;
    color: #6c757d;
    text-align: center;
    max-width: 100px;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

