@using static sv_b1c3234d66ed4d7fa963c8950a97ac66.Components.Pages.Apply

<div class="step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var step = i + 1;
        var isActive = step == CurrentStep;
        var isCompleted = CompletedSteps.Contains(step);
        var isClickable = isCompleted && !isActive;

        <div class="step-item @(isActive ? "active" : "") @(isCompleted && !isActive ? "completed" : "") @(isClickable ? "clickable" : "")"
             @onclick="() => { if (isClickable) OnStepClicked.InvokeAsync(step); }">
            <div class="step-circle">
                @if (isCompleted && !isActive)
                {
                    <span>✓</span>
                }
                else
                {
                    @step
                }
            </div>
            <span class="step-label">@StepNames[i]</span>
        </div>
    }
</div>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

